head.script:
scwin.onpageload = function() {
	categoryData.setJSON([{"label": "A", "value": "A"}, {"label": "B", "value": "B"}]);
	subCategoryData.setJSON([
		{"subCategoryGubun": "A", "value": "A1", "label": "A중분류-1"},
		{"subCategoryGubun": "A", "value": "A2", "label": "A중분류-2"},
		{"subCategoryGubun": "B", "value": "B1", "label": "B중분류-1"},
		{"subCategoryGubun": "B", "value": "B2", "label": "B중분류-2"}
	]);
	subSubCategoryData.setJSON([
		{"subSubCategoryGubun": "A1", "value": "AA1-1", "label": "A중분류-1-소분류1"},
		{"subSubCategoryGubun": "A1", "value": "AA1-2", "label": "A중분류-1-소분류2"},
		{"subSubCategoryGubun": "A2", "value": "AA2-1", "label": "A중분류-2-소분류1"},
		{"subSubCategoryGubun": "A2", "value": "AA2-2", "label": "A중분류-2-소분류2"},
		{"subSubCategoryGubun": "B1", "value": "BB1-1", "label": "B중분류-1-소분류1"},
		{"subSubCategoryGubun": "B1", "value": "BB1-2", "label": "B중분류-1-소분류2"},
		{"subSubCategoryGubun": "B2", "value": "BB2-1", "label": "B중분류-2-소분류1"},
		{"subSubCategoryGubun": "B2", "value": "BB2-2", "label": "B중분류-2-소분류2"}
	]);
	gridViewData.setJSON([
		{"col1": "A", "col2": "A1", "col3": "AA1-1"},
		{"col1": "B", "col2": "B1", "col3": "BB1-1"},
		{"col1": "A", "col2": "A2", "col3": "AA2-1"},
		{"col1": "B", "col2": "B2", "col3": "BB2-1"}
	]);
};

scwin.changeNativeSelectOption = function(optionValue) {
	var selectElem = document.getElementById('mf_gridView1_cell_0_0_select_input_0');
	if (!selectElem) {
		return;
	}
	selectElem.value = optionValue;
	selectElem.dispatchEvent(new Event('change', { bubbles: true }));
};

scwin.checkVal1 = function() {
	return (document.getElementById('gridView1_cell_0_1') || document.getElementById('mf_gridView1_cell_0_1')).innerText.includes('B중분류-1');
};

scwin.checkVal2 = function() {
	return (document.getElementById('gridView1_cell_0_2') || document.getElementById('mf_gridView1_cell_0_2')).innerText.includes('B중분류-1-소분류');
};

w2:gridView.script:
if (colIndex == 0) {
	gridViewData.setCellData(rowIndex, "col2", linkedSubCategoryData.getCellData(0, "value"));
	gridViewData.setCellData(rowIndex, "col3", linkedSubSubCategoryData.getCellData(0, "value"));
}
if (colIndex == 1) {
	gridViewData.setCellData(rowIndex, "col3", linkedSubSubCategoryData.getCellData(0, "value"));
}
